import Foundation
import ZEUVECore
public struct CleanerHistoryPayload:Codable,Sendable,Equatable{public let kind:String;public let removed:Int;public let skipped:Int;public let failed:Int;public let logicalBytes:Int64;public let undoAvailable:Bool}
public struct CleanerHistoryPresenter:ModuleHistoryPresenter{public let moduleID=cleanerModuleIdentifier;public init(){};public func presentation(for record:OperationHistoryRecord)->ModuleHistoryPresentation{guard let p=try? JSONDecoder().decode(CleanerHistoryPayload.self,from:record.payload) else{return GenericModuleHistoryPresenter(moduleID:moduleID).presentation(for:record)};return .init(title:p.kind == "uninstall" ? "Desinstalación asistida":"Limpieza",subtitle:"\(p.removed) eliminados · \(p.skipped) omitidos · \(p.failed) fallidos",details:["Tamaño lógico procesado: \(ByteCountFormatter.string(fromByteCount:p.logicalBytes,countStyle:.file))",p.undoAvailable ? "Deshacer disponible mientras los elementos sigan verificables en la Papelera.":"Deshacer no disponible."])}}
